import re
def find_tandem(s, min_unit=4, min_copies=2, max_unit=60):
    hits=[]
    n=len(s)
    for u in range(min_unit, max_unit+1):
        for i in range(0, n-2*u+1):
            unit=s[i:i+u]
            cnt=1
            j=i+u
            while j+u<=n and s[j:j+u]==unit:
                cnt+=1; j+=u
            if cnt>=min_copies:
                hits.append((u,cnt,i,j,unit))
    return hits
